import fs from "fs";
import path from "path";
import { pool } from "./db.js";

export const HEIC_PATCHES = [
  {
    "jpgFilename": "photo_1789923419577_ob1hmf.jpg",
    "heicFilename": "photo_1789923419577_ob1hmf.heic",
    "base64Data": ""
  },
  {
    "jpgFilename": "photo_1789928441157_xibwtf.jpg",
    "heicFilename": "photo_1789928441157_xibwtf.heic",
    "base64Data": ""
  },
  {
    "jpgFilename": "photo_1789929126099_p4rjm4.jpg",
    "heicFilename": "photo_1789929126099_p4rjm4.heic",
    "base64Data": ""
  },
  {
    "jpgFilename": "photo_1789931895799_xcksva.jpg",
    "heicFilename": "photo_1789931895799_xcksva.heic",
    "base64Data": ""
  }
];

export async function applyHeicBackfill() {
  const candidateDirs = Array.from(
    new Set(
      [
        process.env.UPLOADS_DIR,
        "/data/uploads",
        "/data",
        "/app/data/uploads",
        "/app/data",
        "/app/public/uploads",
        "/app/uploads",
        path.resolve(process.cwd(), "public/uploads"),
        path.resolve(process.cwd(), "uploads"),
      ].filter((d): d is string => Boolean(d))
    )
  );

  for (const patch of HEIC_PATCHES) {
    try {
      const buffer = Buffer.from(patch.base64Data, "base64");

      // 1. Write the valid converted JPEG buffer directly to ALL candidate disk directories!
      // Write to both .jpg and .heic filename so any request gets the valid JPEG bytes.
      for (const dir of candidateDirs) {
        try {
          fs.mkdirSync(dir, { recursive: true });
          fs.writeFileSync(path.join(dir, patch.jpgFilename), buffer);
          fs.writeFileSync(path.join(dir, patch.heicFilename), buffer);
        } catch (diskErr) {
          console.error("Error writing patch to disk dir " + dir + ":", diskErr);
        }
      }

      // 2. Update PostgreSQL uploaded_files table
      if (process.env.DATABASE_URL && pool) {
        await pool.query(
          `INSERT INTO uploaded_files (filename, mime_type, data)
           VALUES ($1, 'image/jpeg', $2)
           ON CONFLICT (filename) DO UPDATE SET data = EXCLUDED.data, mime_type = 'image/jpeg'`,
          [patch.jpgFilename, buffer],
        );

        await pool.query(
          `INSERT INTO uploaded_files (filename, mime_type, data)
           VALUES ($1, 'image/jpeg', $2)
           ON CONFLICT (filename) DO UPDATE SET data = EXCLUDED.data, mime_type = 'image/jpeg'`,
          [patch.heicFilename, buffer],
        );

        // 3. Update candidate answers in application_submissions
        const oldUrl = `/uploads/${patch.heicFilename}`;
        const newUrl = `/uploads/${patch.jpgFilename}`;
        await pool.query(
          `UPDATE application_submissions
           SET answers = jsonb_set(
             answers,
             ARRAY[key],
             to_jsonb($2::text)
           )
           FROM (
             SELECT id, key
             FROM application_submissions, jsonb_each_text(answers)
             WHERE value = $1
           ) sub
           WHERE application_submissions.id = sub.id`,
          [oldUrl, newUrl],
        );
      }

      console.log(`Successfully backfilled and cached to disk: ${patch.heicFilename} -> ${patch.jpgFilename}`);
    } catch (err) {
      console.error(`Error backfilling ${patch.heicFilename}:`, err);
    }
  }
}
